import{_ as a,o as i,c as s,a3 as t}from"./chunks/framework.BTQ4eCVb.js";const m=JSON.parse('{"title":"Email — Deployment","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Email — Deployment | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/email"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Email — Deployment | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/email"}]]},"headers":[],"relativePath":"deployment/email.md","filePath":"deployment/email.md","lastUpdated":1788108809000}'),o={name:"deployment/email.md"};function n(l,e,r,d,c,p){return i(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="email-—-deployment" tabindex="-1">Email — Deployment <a class="header-anchor" href="#email-—-deployment" aria-label="Permalink to &quot;Email — Deployment&quot;">​</a></h1><h2 id="production-deploy-migrate-only" tabindex="-1">Production deploy (migrate-only) <a class="header-anchor" href="#production-deploy-migrate-only" aria-label="Permalink to &quot;Production deploy (migrate-only)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> optimize</span></span></code></pre></div><p>This ships:</p><ol><li>Schema for <code>email_accounts</code>, <code>email_folders</code>, <code>email_labels</code>, <code>email_message_label</code>, <code>email_messages</code>, <code>email_attachments</code>, <code>email_signatures</code>, <code>email_templates</code>, <code>email_message_links</code></li><li>Catalog row for free opt-in module <code>email</code> (data migration — <strong>not</strong> default-included); later migrations bump catalog version (e.g. <strong>1.1.0</strong> shared templates, <strong>1.2.0</strong> EloSync labels, <strong>1.3.0</strong> reading-pane layout + multi-select bulk API) via <code>DefaultModuleRegistrar::bumpVersion</code></li><li>Additive permission grants for default roles (<code>email.*</code>)</li><li>Additive template column <code>is_shared</code> (existing rows backfilled private)</li></ol><p>Do <strong>not</strong> run <code>db:seed</code>, <code>CatalogSeeder</code>, or any permission seeder in production for this module.</p><h2 id="php-imap-extension" tabindex="-1">PHP IMAP extension <a class="header-anchor" href="#php-imap-extension" aria-label="Permalink to &quot;PHP IMAP extension&quot;">​</a></h2><p>Personal sync uses PHP’s native <code>imap_*</code> API (<code>NativeImapMailboxClient</code>). Ensure <code>ext-imap</code> is enabled on <strong>every</strong> app and queue host that runs sync/connect:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> imap</span></span></code></pre></div><p>Without the extension, account test/sync fails with a clear runtime error. Do not rely on Composer IMAP packages for v1.</p><p>On <strong>PHP 8.4+</strong>, IMAP is unbundled (PECL). Windows / Laravel Herd:</p><ol><li>Download the matching NTS build from <a href="https://downloads.php.net/~windows/pecl/releases/imap/" target="_blank" rel="noreferrer">PECL imap Windows releases</a> (e.g. <code>php_imap-1.0.3-8.4-nts-vs17-x64.zip</code> for Herd PHP 8.4 NTS x64).</li><li>Copy <code>php_imap.dll</code> into the PHP <code>ext</code> directory (Herd: <code>%USERPROFILE%\\.config\\herd\\bin\\php84\\ext\\</code>).</li><li>Add <code>extension=imap</code> to that version’s <code>php.ini</code>, then <code>herd restart</code>.</li><li>Confirm with <code>php -m</code> (must list <code>imap</code>).</li></ol><h2 id="queue-worker-email-sync" tabindex="-1">Queue worker (<code>email-sync</code>) <a class="header-anchor" href="#queue-worker-email-sync" aria-label="Permalink to &quot;Queue worker (`email-sync`)&quot;">​</a></h2><p>Sync and outbound personal send jobs use the <strong><code>email-sync</code></strong> queue (not the platform <code>emails</code> notification queue).</p><h3 id="local-supervisor" tabindex="-1">Local / Supervisor <a class="header-anchor" href="#local-supervisor" aria-label="Permalink to &quot;Local / Supervisor&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue:work</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> redis</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --queue=email-sync</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --sleep=1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tries=3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --timeout=300</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --max-time=3600</span></span></code></pre></div><p>Keep personal mailbox jobs separate from transactional <code>emails</code> / <code>emails-high</code> capacity. After credential or queue config changes, restart workers.</p><h3 id="laravel-forge-daemon-recommended" tabindex="-1">Laravel Forge daemon (recommended) <a class="header-anchor" href="#laravel-forge-daemon-recommended" aria-label="Permalink to &quot;Laravel Forge daemon (recommended)&quot;">​</a></h3><p>Add a <strong>second</strong> API daemon (do not mix into the notifications worker):</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Command</td><td><code>php artisan queue:work redis --queue=email-sync --sleep=1 --tries=3 --timeout=300 --max-time=3600</code></td></tr><tr><td>User</td><td><code>forge</code></td></tr><tr><td>Directory</td><td>Same as the API release root (<code>…/current</code> or site path)</td></tr><tr><td>Processes</td><td><code>1</code> (scale if many concurrent mailbox syncs)</td></tr></tbody></table><p>Ensure PHP <code>ext-imap</code> is enabled on the Forge server (see above). Deploy scripts should already run <code>queue:restart</code> so both daemons pick up new code.</p><h2 id="scheduler" tabindex="-1">Scheduler <a class="header-anchor" href="#scheduler" aria-label="Permalink to &quot;Scheduler&quot;">​</a></h2><p>Enable Forge <strong>Scheduler</strong> (<code>schedule:run</code> every minute). The Email module registers:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> email:sync</span></span></code></pre></div><p><strong>every minute</strong> with <code>withoutOverlapping</code> + <code>onOneServer</code>. The command only dispatches <code>SyncEmailAccountJob</code> for accounts that are due based on each mailbox’s <code>sync_interval_minutes</code> (default <strong>5</strong>, options 5 / 10 / 15 / 30 / 60). Manual Sync from the SPA always dispatches immediately.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> php /path/to/artisan schedule:run</span></span></code></pre></div><h2 id="attachment-storage-deferred" tabindex="-1">Attachment storage (deferred) <a class="header-anchor" href="#attachment-storage-deferred" aria-label="Permalink to &quot;Attachment storage (deferred)&quot;">​</a></h2><p>The <code>email_attachments</code> table and client helpers exist for a future download/compose path. <strong>v1 sync does not persist attachment files</strong> to disk; it may set <code>has_attachments</code> from IMAP headers only. Prefer a private disk and monitor growth when that path ships.</p><p>Personal attachments are unrelated to platform email log body storage (<code>EMAIL_LOGS_STORE_BODY</code>).</p><h2 id="what-the-data-migrations-do-and-do-not-do" tabindex="-1">What the data migrations do (and do not do) <a class="header-anchor" href="#what-the-data-migrations-do-and-do-not-do" aria-label="Permalink to &quot;What the data migrations do (and do not do)&quot;">​</a></h2><h3 id="register-email-module" tabindex="-1"><code>register_email_module</code> <a class="header-anchor" href="#register-email-module" aria-label="Permalink to &quot;`register_email_module`&quot;">​</a></h3><p>Uses <code>App\\Support\\Catalog\\DefaultModuleRegistrar</code>:</p><ul><li>Ensures Communication category + <code>email</code> catalog row <strong>if missing</strong></li><li><code>is_default_included=false</code>, <code>is_billable=false</code>, monthly/yearly <code>0</code></li><li>Does <strong>not</strong> auto-install for existing or new workspaces</li><li>Never overwrites commercial flags if the row already exists</li></ul><h3 id="add-email-permissions" tabindex="-1"><code>add_email_permissions</code> <a class="header-anchor" href="#add-email-permissions" aria-label="Permalink to &quot;`add_email_permissions`&quot;">​</a></h3><p>Uses <code>App\\Support\\Permissions\\TenantPermissionSynchronizer</code>:</p><ul><li>Creates missing <code>email.*</code> vocabulary</li><li>Grants missing defaults to mapped roles (additive only)</li><li>Never <code>syncPermissions()</code> / never revokes customizations</li></ul><h2 id="new-workspaces" tabindex="-1">New workspaces <a class="header-anchor" href="#new-workspaces" aria-label="Permalink to &quot;New workspaces&quot;">​</a></h2><p>Email is <strong>not</strong> in <code>installDefaultModules()</code>. Owners install from Marketplace when needed. RBAC vocabulary exists after migrate; roles receive mapped grants from the permission data migration / provisioning maps.</p><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --compact</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/Feature/Tenant/Email</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> imap</span></span></code></pre></div><p>Frontend (optional):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> EloSync-Frontend</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:e2e:email</span></span></code></pre></div><p>Smoke after deploy:</p><ol><li>Marketplace shows <strong>Email</strong> as free to install</li><li>After install + <code>email.accounts.manage</code>, user can open <code>/email</code> and see <strong>Connect your mailbox</strong></li><li>With <code>ext-imap</code> + worker on <code>email-sync</code>, test connection and sync succeed for app-password mailboxes</li><li>Settings → Mail and notification queues remain unchanged</li><li>User A cannot list User B’s accounts or messages</li></ol><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/deployment/platform-production-runbook">Platform production runbook</a></li><li><a href="/deployment/module-development">Module development — production</a></li><li><a href="/developer-guide/email">Developer guide</a></li><li><a href="/developer-guide/multi-provider-email">Multi-Provider Email</a> — transactional mail queues (<code>emails</code>)</li></ul>',46)])])}const u=a(o,[["render",n]]);export{m as __pageData,u as default};
